const std = @import("std");
const OptimizeMode = std.builtin.OptimizeMode;

pub fn build(b: *std.Build) void {
    // Production builds always use ReleaseSafe (see AGENTS.md).
    const optimize: OptimizeMode = .ReleaseSafe;

    const host = b.graph.host;
    const host_arch = host.result.cpu.arch;
    const is_macos = host.result.os.tag == .macos;

    // Static liblex, targeting macOS with the host CPU architecture. The app is
    // only ever linked on macOS, so the library arch tracks the build machine
    // and matches swiftc's default architecture.
    const macos_target = b.resolveTargetQuery(.{
        .cpu_arch = host_arch,
        .os_tag = .macos,
        .os_version_min = .{ .semver = .{ .major = 26, .minor = 0, .patch = 0 } },
    });
    const lib = b.addLibrary(.{
        .name = "lex",
        .linkage = .static,
        .root_module = b.createModule(.{
            .root_source_file = b.path("src/lex.zig"),
            .target = macos_target,
            .optimize = optimize,
        }),
    });

    // Unit tests run on the host so they can be exercised on a Linux dev
    // machine (the macOS app cannot be built there).
    const lib_tests = b.addTest(.{
        .root_module = b.createModule(.{
            .root_source_file = b.path("src/lex.zig"),
            .target = host,
            // Debug build for tests to surface issues (extra safety checks,
            // better diagnostics) earlier than the ReleaseSafe production build.
            .optimize = .Debug,
        }),
    });
    const run_lib_tests = b.addRunArtifact(lib_tests);
    const test_step = b.step("test", "Run liblex unit tests on the host");
    test_step.dependOn(&run_lib_tests.step);

    const app_step = b.step("app", "Build Lex.app (ad-hoc signed)");
    const app_unsigned_step = b.step("app-unsigned", "Build Lex.app (unsigned)");
    const run_step = b.step("run", "Build and open Lex.app");

    // Off macOS the app pipeline cannot run; surface a clear notice instead of
    // failing on a missing swiftc/codesign.
    if (!is_macos) {
        const notice = b.addSystemCommand(&.{
            "echo",
            "Lex.app can only be built on macOS. On this host run `zig build test`.",
        });
        app_step.dependOn(&notice.step);
        app_unsigned_step.dependOn(&notice.step);
        run_step.dependOn(&notice.step);
        b.getInstallStep().dependOn(&notice.step);
        return;
    }

    // --- macOS build pipeline ---

    // swiftc target triple, e.g. "arm64-apple-macosx26.0".
    const swift_arch = switch (host_arch) {
        .aarch64 => "arm64",
        .x86_64 => "x86_64",
        else => @panic("unsupported host architecture for macOS build"),
    };
    const swift_target = b.fmt("{s}-apple-macosx26.0", .{swift_arch});

    // Ensure the bundle's executable directory exists before swiftc writes to it.
    const mkdir = b.addSystemCommand(&.{ "mkdir", "-p", "macos/Lex.app/Contents/MacOS" });
    mkdir.has_side_effects = true;

    // Re-pack the archive (workaround for non-8-byte-aligned archive members
    // that Apple's linker rejects).
    const repack = b.addSystemCommand(&.{
        "/bin/sh", "-c",
        \\tmp=$(mktemp -d) && \
        \\cp "$1" "$tmp/lib.a" && \
        \\(cd "$tmp" && ar x lib.a && rm lib.a && chmod 644 *.o && /usr/bin/ar rcs lib.a *.o) && \
        \\cp "$tmp/lib.a" "$1" && \
        \\rm -rf "$tmp"
        ,
        "--",
    });
    repack.addArtifactArg(lib);
    repack.has_side_effects = true;

    // Remove any stale code signature before writing the new binary so an
    // unsigned build is cleanly unsigned (and a re-sign starts fresh).
    const strip_sig = b.addSystemCommand(&.{ "rm", "-rf", "macos/Lex.app/Contents/_CodeSignature" });
    strip_sig.has_side_effects = true;

    // Compile Swift and statically link liblex.
    const swiftc = b.addSystemCommand(&.{
        "swiftc",
        "-parse-as-library",
        "-target",
        swift_target,
        "macos/Lex.swift",
        "-import-objc-header",
        "src/lex.h",
    });
    swiftc.addPrefixedDirectoryArg("-L", lib.getEmittedBinDirectory());
    swiftc.addArgs(&.{"-llex"});
    swiftc.addArgs(&.{ "-o", "macos/Lex.app/Contents/MacOS/Lex" });
    swiftc.step.dependOn(&mkdir.step);
    swiftc.step.dependOn(&repack.step);
    swiftc.step.dependOn(&strip_sig.step);
    swiftc.has_side_effects = true;

    // app-unsigned: stop after swiftc, leaving the bundle unsigned.
    app_unsigned_step.dependOn(&swiftc.step);

    // app: ad-hoc codesign the bundle.
    const codesign = b.addSystemCommand(&.{ "codesign", "-f", "-s", "-", "macos/Lex.app" });
    codesign.step.dependOn(&swiftc.step);
    codesign.has_side_effects = true;
    app_step.dependOn(&codesign.step);

    // Default `zig build` builds the signed app.
    b.getInstallStep().dependOn(&codesign.step);

    // run: open the signed app.
    const open = b.addSystemCommand(&.{ "open", "macos/Lex.app" });
    open.step.dependOn(&codesign.step);
    run_step.dependOn(&open.step);
}

const std = @import("std");

const assert = std.debug.assert;
const expectEqual = std.testing.expectEqual;
const indexOfScalar = std.mem.indexOfScalar;
const isAlphabetic = std.ascii.isAlphabetic;
const maxInt = std.math.maxInt;
const toUpper = std.ascii.toUpper;

const Diacritic = enum(u8) {
    empty, // nguyên âm, không dấu.
    circumflex, // dấu nón: â, ô, ê.
    horn, // dấu móc: ư, ơ.
    breve, // dấu ă.
    stroke, // dấu gạch: đ.
};

const Tone = enum(u8) {
    level, // thanh ngang, không dấu.
    rising, // sắc.
    falling, // huyền.
    dipping_rising, // hỏi.
    rising_glottalized, // ngã.
    falling_glottalized, // nặng.
};

const Span = struct {
    // Alphabet ASCII character, could be lowercase or uppercase.
    base: u8,
    // By default, it's plain alphabet character.
    diacritic: Diacritic = .empty,
    // By default, no tone is placed.
    tone: Tone = .level,

    // Create a Span with plain alphabet character, no diacritic, no tone.
    fn init(base: u8) Span {
        return Span.init_diacritic_tone(base, .empty, .level);
    }

    // Create a Span with diacritic, no tone.
    fn init_diacritic(base: u8, diacritic: Diacritic) Span {
        return Span.init_diacritic_tone(base, diacritic, .level);
    }

    fn init_diacritic_tone(base: u8, diacritic: Diacritic, tone: Tone) Span {
        // Only allow a-zA-Z.
        assert(isAlphabetic(base));

        // Only allow a valid Vietnamese alphabet combinations.
        switch (diacritic) {
            // All alphabet is allowed without diacritic.
            .empty => {},
            // Only a, o, e are valid with circumflex.
            .circumflex => switch (base) {
                'A', 'E', 'O', 'a', 'e', 'o' => {},
                else => unreachable,
            },
            // Only u, o are valid with horn.
            .horn => switch (base) {
                'O', 'U', 'o', 'u' => {},
                else => unreachable,
            },
            // Only a is valid with breve.
            .breve => switch (base) {
                'A', 'a' => {},
                else => unreachable,
            },
            // Only d is valid with stroke.
            .stroke => switch (base) {
                'D', 'd' => {},
                else => unreachable,
            },
        }

        // Only allow tone on valid Vietnamese vowels based on Vietnamese rules.
        switch (tone) {
            // All alphabet is allowed with level.
            .level => {},
            // All vowels is allowed with remaining tones.
            .rising, .falling, .dipping_rising, .rising_glottalized, .falling_glottalized => switch (base) {
                'A', 'E', 'I', 'O', 'U', 'Y', 'a', 'e', 'i', 'o', 'u', 'y' => {},
                else => unreachable,
            },
        }

        return .{ .base = base, .diacritic = diacritic, .tone = tone };
    }

    // Compare only base character, ignore case and other aspects.
    fn equals_ignore_case_diacritic_tone(self: *const Span, base: u8) bool {
        // Base must be alphabet letters.
        assert(isAlphabetic(base));

        return toUpper(self.base) == toUpper(base);
    }

    // Compare the span with a base character (ignore case) and diacritic, tone is ignored.
    fn equals_ignore_case_tone(self: *const Span, base: u8, diacritic: Diacritic) bool {
        // Base must be alphabet letters.
        assert(isAlphabetic(base));

        return toUpper(self.base) == toUpper(base) and self.diacritic == diacritic;
    }

    // Compare the Span base (ignore case), diacritic, tone.
    fn equals_ignore_case(self: *const Span, base: u8, diacritic: Diacritic, tone: Tone) bool {
        // Base must be alphabet letters.
        assert(isAlphabetic(base));

        return toUpper(self.base) == toUpper(base) and self.diacritic == diacritic and self.tone == tone;
    }

    // Check if the Span.base is vowel or not.
    fn is_vowel(self: *const Span) bool {
        return switch (toUpper(self.base)) {
            'A', 'E', 'I', 'O', 'U', 'Y' => true,
            else => false,
        };
    }

    // Check if the Span.base is consonant or not.
    fn is_consonant(self: *const Span) bool {
        return !self.is_vowel();
    }

    fn to_utf16(self: *const Span) u16 {
        assert(isAlphabetic(self.base));

        // fast path, plain alphabet.
        if (self.diacritic == .empty and self.tone == .level) {
            return self.base;
        }

        switch (self.base) {
            'a' => {
                switch (self.diacritic) {
                    .empty => {
                        switch (self.tone) {
                            .level => unreachable,
                            .rising => return 0x00E1, // á.
                            .falling => return 0x00E0, // à.
                            .dipping_rising => return 0x1EA3, // ả.
                            .rising_glottalized => return 0x00E3, // ã.
                            .falling_glottalized => return 0x1EA1, // ạ.
                        }
                    },
                    .breve => {
                        switch (self.tone) {
                            .level => return 0x0103, // ă.
                            .rising => return 0x1EAF, // ắ.
                            .falling => return 0x1EB1, // ằ.
                            .dipping_rising => return 0x1EB3, // ẳ.
                            .rising_glottalized => return 0x1EB5, // ẵ.
                            .falling_glottalized => return 0x1EB7, // ặ.
                        }
                    },
                    .circumflex => {
                        switch (self.tone) {
                            .level => return 0x00E2, // â.
                            .rising => return 0x1EA5, // ấ.
                            .falling => return 0x1EA7, // ầ.
                            .dipping_rising => return 0x1EA9, // ẩ.
                            .rising_glottalized => return 0x1EAB, // ẫ.
                            .falling_glottalized => return 0x1EAD, // ậ.
                        }
                    },
                    .horn, .stroke => unreachable,
                }
            },
            'A' => {
                switch (self.diacritic) {
                    .empty => {
                        switch (self.tone) {
                            .level => unreachable,
                            .rising => return 0x00C1, // Á.
                            .falling => return 0x00C0, // À.
                            .dipping_rising => return 0x1EA2, // Ả.
                            .rising_glottalized => return 0x00C3, // Ã.
                            .falling_glottalized => return 0x1EA0, // Ạ.
                        }
                    },
                    .breve => {
                        switch (self.tone) {
                            .level => return 0x0102, // Ă.
                            .rising => return 0x1EAE, // Ắ.
                            .falling => return 0x1EB0, // Ằ.
                            .dipping_rising => return 0x1EB2, // Ẳ.
                            .rising_glottalized => return 0x1EB4, // Ẵ.
                            .falling_glottalized => return 0x1EB6, // Ặ.
                        }
                    },
                    .circumflex => {
                        switch (self.tone) {
                            .level => return 0x00C2, // Â.
                            .rising => return 0x1EA4, // Ấ.
                            .falling => return 0x1EA6, // Ầ.
                            .dipping_rising => return 0x1EA8, // Ẩ.
                            .rising_glottalized => return 0x1EAA, // Ẫ.
                            .falling_glottalized => return 0x1EAC, // Ậ.
                        }
                    },
                    .horn, .stroke => unreachable,
                }
            },
            'd' => {
                assert(self.diacritic == .stroke);
                assert(self.tone == .level);
                return 0x0111; // đ.
            },
            'D' => {
                assert(self.diacritic == .stroke);
                assert(self.tone == .level);
                return 0x0110; // Đ.
            },
            'e' => {
                switch (self.diacritic) {
                    .empty => {
                        switch (self.tone) {
                            .level => unreachable,
                            .rising => return 0x00E9, // é.
                            .falling => return 0x00E8, // è.
                            .dipping_rising => return 0x1EBB, // ẻ.
                            .rising_glottalized => return 0x1EBD, // ẽ.
                            .falling_glottalized => return 0x1EB9, // ẹ.
                        }
                    },
                    .circumflex => {
                        switch (self.tone) {
                            .level => return 0x00EA, // ê.
                            .rising => return 0x1EBF, // ế.
                            .falling => return 0x1EC1, // ề.
                            .dipping_rising => return 0x1EC3, // ể.
                            .rising_glottalized => return 0x1EC5, // ễ.
                            .falling_glottalized => return 0x1EC7, // ệ.
                        }
                    },
                    .horn, .breve, .stroke => unreachable,
                }
            },
            'E' => {
                switch (self.diacritic) {
                    .empty => {
                        switch (self.tone) {
                            .level => unreachable,
                            .rising => return 0x00C9, // É.
                            .falling => return 0x00C8, // È.
                            .dipping_rising => return 0x1EBA, // Ẻ.
                            .rising_glottalized => return 0x1EBC, // Ẽ.
                            .falling_glottalized => return 0x1EB8, // Ẹ.
                        }
                    },
                    .circumflex => {
                        switch (self.tone) {
                            .level => return 0x00CA, // Ê.
                            .rising => return 0x1EBE, // Ế.
                            .falling => return 0x1EC0, // Ề.
                            .dipping_rising => return 0x1EC2, // Ể.
                            .rising_glottalized => return 0x1EC4, // Ễ.
                            .falling_glottalized => return 0x1EC6, // Ệ.
                        }

#ifndef LEX_H
