258:                     std.debug.print("SKIP\n", .{});
259:                 }
260:                 test_node.end();

260:                 test_node.end();
261:             },
262:             else => {
263:                 fail_count += 1;
264:                 if (have_tty) {
265:                     std.debug.print("{d}/{d} {s}...FAIL ({t})\n", .{
266:                         i + 1, test_fn_list.len, test_fn.name, err,
267:                     });
268:                 } else {
269:                     std.debug.print("FAIL ({t})\n", .{err});
270:                 }
271:                 if (@errorReturnTrace()) |trace| {
