1775:    // Reset all tones in vowels to level. If word has no tone, this function is no-op.
1776:    fn reset_tone(self: *State, word: Pseudoword, tone_index: u8) void {
1777:        // The word must have vowels.
1778:        assert(word.has_vowels());
1779:        // tone_index on vowels.
1780:        assert(tone_index >= word.vowels_start.? and tone_index <= word.vowels_end.?);
1781:
1782:        // Reset tone.
1783:        const sp = self.buffer_effective[tone_index];
1784:        self.buffer_effective[tone_index] = Span.init_diacritic_tone(sp.base, sp.diacritic, .level);
1785:        // Set buffer_modification_index to the earliest modification.
1786:        if (self.buffer_modification_index == null or tone_index < self.buffer_modification_index.?) {
1787:            self.buffer_modification_index = tone_index;
1788:        }
1789:    }
1790:
1791:    fn backspace(self: *State) void {
1792:        // buffer_length must be positive for backspace.
1793:        assert(self.buffer_length > 0);
1794:
1795:        if (self.literal_index) |literal_index| {
1796:            // literal_index must be within buffer_effective range when set.
1797:            assert(literal_index < self.buffer_effective.len);
1798:            // literal_index must be less than buffer_length.
1799:            assert(literal_index < self.buffer_length);
1800:        }
1801:
1802:        // decrease the buffer_length to match the backspace.
1803:        self.buffer_length -= 1;
1804:        // because backspace doesn't retro-modify the buffer, unset the buffer_modification_index.
1805:        self.buffer_modification_index = null;
1806:        // if the literal_index is out of buffer range, unset it.
1807:        if (self.literal_index != null and self.literal_index.? == self.buffer_length) {
1808:            self.literal_index = null;
1809:        }
1810:    }
1811:
1812:    // Calculate how many backspaces are needed to completely replace the existing characters to
1813:    // make them match with the new state.
1814:    fn calculate_synthetic_backspaces(self: *State) u8 {
1815:        // The previous length must have valid value.
1816:        assert(self.buffer_length_previous <= self.buffer_length);
1817:        assert(self.buffer_modification_index == null or (self.buffer_modification_index.? < self.buffer_length_previous));
1818:
1819:        if (self.buffer_modification_index) |buffer_modification_index| {
1820:            return self.buffer_length_previous - buffer_modification_index;
1821:        } else {
1822:            return 0;
1823:        }
1824:    }
1825:
1826:    // Compose UTF-16 string replacement for the synthetic events. It could be multiple characters
1827:    // or one literal character.
1828:    fn compose_utf16_string_replacement(self: *State, replacement_buffer: *[buffer_effective_length]u16, replacement_count: *u8) void {
1829:        // The buffer must have character.
1830:        assert(self.buffer_length > 0);
1831:        // The buffer_length must be within buffer_effective.
1832:        assert(self.buffer_length <= self.buffer_effective.len);
1833:
1834:        if (self.buffer_modification_index) |buffer_modification_index| {
1835:            // The previous action has modified buffer_effective.
1836:            // Iterate from the buffer_modification_index to compose the replacement.
1837:            for (buffer_modification_index..self.buffer_length) |i| {
1838:                replacement_buffer[i - buffer_modification_index] = self.buffer_effective[i].to_utf16();
1839:            }
1840:            // Calculate replacement_count.
1841:            replacement_count.* = self.buffer_length - buffer_modification_index;
1842:        } else {
1843:            // The previous action only added one character literally, no retrospect editing.
1844:            assert((self.buffer_length - self.buffer_length_previous) == 1);
1845:
1846:            replacement_buffer[0] = self.buffer_effective[self.buffer_length - 1].to_utf16();
1847:            replacement_count.* = 1;
1848:        }
1849:    }
1850:
1851:    // Indicate if the buffer_effective is full.
1852:    fn buffer_effective_full(self: *State) bool {
1853:        if (self.buffer_length < self.buffer_effective.len) {
1854:            return false;
1855:        } else {

1840:            // Calculate replacement_count.
1841:            replacement_count.* = self.buffer_length - buffer_modification_index;
1842:        } else {
1843:            // The previous action only added one character literally, no retrospect editing.
1844:            assert((self.buffer_length - self.buffer_length_previous) == 1);
1845:
1846:            replacement_buffer[0] = self.buffer_effective[self.buffer_length - 1].to_utf16();
1847:            replacement_count.* = 1;
1848:        }
1849:    }
1850:
1851:    // Indicate if the buffer_effective is full.
1852:    fn buffer_effective_full(self: *State) bool {
1853:        if (self.buffer_length < self.buffer_effective.len) {
1854:            return false;
1855:        } else {
1856:            assert(self.literal_index != null and self.literal_index.? < self.buffer_effective.len);
1857:            return true;
1858:        }
1859:    }
1860:};
