+test "fuzz public ABI operation streams" {
+    const Harness = struct {
+        const visible_capacity = 512;
+        const max_operation_count = 160;
+        const replacement_sentinel = 0xFFFF;
+
+        const Operation = enum(u8) {
+            add,
+            backspace,
+            reset,
+            query,
+            add_again,
+        };
+
+        fn fuzz_one(_: void, smith: *std.testing.Smith) !void {
+            const raw_pointer = std.testing.allocator.rawAlloc(lex_state_size, .fromByteUnits(lex_state_alignment), @returnAddress()) orelse return error.OutOfMemory;
+            defer std.testing.allocator.rawFree(raw_pointer[0..lex_state_size], .fromByteUnits(lex_state_alignment), @returnAddress());
+
+            lex_init(raw_pointer);
+
+            var visible_buffer: [visible_capacity]u16 = undefined;
+            var visible_length: usize = 0;
+            var word_start: usize = 0;
+
+            var header: [1]u8 = undefined;
+            smith.bytes(&header);
+            const operation_count = @min(header[0], max_operation_count);
+
+            for (0..operation_count) |_| {
+                var operation_bytes: [2]u8 = undefined;
+                smith.bytes(&operation_bytes);
+
+                const operation: Operation = @enumFromInt(operation_bytes[0] % 5);
+                switch (operation) {
+                    .add, .add_again => {
+                        const c = alphabetic_character(operation_bytes[1]);
+                        if (lex_buffer_full(raw_pointer)) {
+                            lex_init(raw_pointer);
+                            word_start = visible_length;
+                        }
+
+                        if (lex_buffer_effective_full(raw_pointer)) {
+                            lex_add(raw_pointer, c);
+                            try append_visible(&visible_buffer, &visible_length, c);
+                        } else {
+                            lex_add(raw_pointer, c);
+
+                            const synthetic_backspaces = lex_calculate_synthetic_backspaces(raw_pointer);
+                            try std.testing.expect(synthetic_backspaces <= visible_length - word_start);
+                            visible_length -= synthetic_backspaces;
+
+                            var replacement_buffer: [lex_replacement_buffer_length]u16 = undefined;
+                            @memset(&replacement_buffer, replacement_sentinel);
+                            var replacement_count: u8 = undefined;
+                            lex_compose_utf16_string_replacement(raw_pointer, &replacement_buffer, &replacement_count);
+
+                            try std.testing.expect(replacement_count > 0);
+                            try std.testing.expect(replacement_count <= lex_replacement_buffer_length);
+
+                            const replacement_length: usize = replacement_count;
+                            for (replacement_buffer[0..replacement_length]) |replacement_character| {
+                                try std.testing.expect(is_allowed_replacement_character(replacement_character));
+                            }
+                            for (replacement_buffer[replacement_length..]) |replacement_character| {
+                                try expectEqual(@as(u16, replacement_sentinel), replacement_character);
+                            }
+
+                            try append_visible_slice(&visible_buffer, &visible_length, replacement_buffer[0..replacement_length]);
+                        }
+
+                        try std.testing.expect(!lex_buffer_empty(raw_pointer));
+                        try query_invariants(raw_pointer);
+                    },
+                    .backspace => {
+                        if (!lex_buffer_empty(raw_pointer)) {
+                            try std.testing.expect(visible_length > word_start);
+                            lex_backspace(raw_pointer);
+                            visible_length -= 1;
+                            try query_invariants(raw_pointer);
+                        }
+                    },
+                    .reset => {
+                        lex_init(raw_pointer);
+                        word_start = visible_length;
+                        try query_invariants(raw_pointer);
+                    },
+                    .query => {
+                        try query_invariants(raw_pointer);
+                    },
+                }
+            }
+        }
+
+        fn alphabetic_character(raw: u8) u8 {
+            const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
+            const index: usize = @intCast(raw % 52);
+            return alphabet[index];
+        }
+
+        fn append_visible(buffer: *[visible_capacity]u16, length: *usize, character: u16) !void {
+            try std.testing.expect(length.* < buffer.len);
+            buffer[length.*] = character;
+            length.* += 1;
+        }
+
+        fn append_visible_slice(buffer: *[visible_capacity]u16, length: *usize, characters: []const u16) !void {
+            try std.testing.expect(length.* + characters.len <= buffer.len);
+            for (characters) |character| {
+                buffer[length.*] = character;
+                length.* += 1;
+            }
+        }
+
+        fn query_invariants(state: *anyopaque) !void {
+            const buffer_empty = lex_buffer_empty(state);
+            const buffer_full = lex_buffer_full(state);
+            const buffer_effective_full = lex_buffer_effective_full(state);
+
+            if (buffer_empty) {
+                try std.testing.expect(!buffer_full);
+                try std.testing.expect(!buffer_effective_full);
+            }
+
+            if (buffer_full) {
+                try std.testing.expect(buffer_effective_full);
+            }
+        }
+
+        fn is_allowed_replacement_character(character: u16) bool {
+            if ((character >= 'A' and character <= 'Z') or (character >= 'a' and character <= 'z')) {
+                return true;
+            }
+
+            return switch (character) {
+                0x00C0, 0x00C1, 0x00C2, 0x00C3, 0x00C8, 0x00C9, 0x00CA, 0x00CC, 0x00CD, 0x00D2, 0x00D3, 0x00D4, 0x00D5, 0x00D9, 0x00DA, 0x00DD,
+                0x00E0, 0x00E1, 0x00E2, 0x00E3, 0x00E8, 0x00E9, 0x00EA, 0x00EC, 0x00ED, 0x00F2, 0x00F3, 0x00F4, 0x00F5, 0x00F9, 0x00FA, 0x00FD,
+                0x0102, 0x0103, 0x0110, 0x0111, 0x0128, 0x0129, 0x0168, 0x0169, 0x01A0, 0x01A1, 0x01AF, 0x01B0,
+                => true,
+                0x1EA0...0x1EF9 => true,
+                else => false,
+            };
+        }
+    };
+
+    const corpus = [_][]const u8{
