        &.{ 1, 0, 9 },
        &.{ 1, 0, 22 },
        &.{ 1, 0, 25 },
        &.{ 2, 0, 26, 0, 26 },
        &.{ 2, 0, 0, 0, 48 },
        &.{ 2, 0, 29, 0, 29 },
        &.{ 3, 0, 26, 0, 26, 0, 26 },
        &.{ 5, 0, 39, 0, 46, 0, 40, 0, 48, 0, 28 },
        &.{ 3, 0, 42, 0, 46, 0, 44 },
        &.{ 4, 0, 32, 0, 34, 0, 26, 0, 31 },
        &.{ 3, 0, 40, 0, 26, 0, 31 },
        &.{ 5, 0, 26, 0, 44, 2, 0, 0, 26, 0, 31 },
        &.{ 5, 0, 26, 0, 26, 0, 26, 1, 0, 0, 26 },
        &.{ 17, 0, 27, 0, 27, 0, 27, 0, 27, 0, 27, 0, 27, 0, 27, 0, 27, 0, 27, 0, 27, 0, 27, 0, 27, 0, 27, 0, 27, 0, 27, 0, 27, 0, 27 },
        &.{ 20, 0, 39, 0, 46, 0, 40, 0, 48, 0, 28, 3, 0, 1, 0, 1, 0, 1, 0, 2, 0, 0, 42, 0, 46, 0, 40, 0, 26, 0, 31, 3, 0, 1, 0, 1, 0, 0, 25 },
    };

    try std.testing.fuzz({}, Harness.fuzz_one, .{ .corpus = &corpus });
}

