+test "fuzz public ABI app-flow operation streams" {
+    const Harness = struct {
+        const max_operation_count = 160;
+
+        fn fuzz_one(_: void, smith: *std.testing.Smith) !void {
+            var engine = try FuzzHarness.Engine.init();
+            defer engine.deinit();
+
+            const operation_count = smith.valueRangeAtMost(u8, 0, max_operation_count);
+            for (0..operation_count) |_| {
+                const operation = FuzzHarness.choose_app_operation(smith);
+                switch (operation) {
+                    .add, .add_again => try engine.add_app_path(FuzzHarness.choose_character(smith)),
+                    .backspace => try engine.backspace(),
+                    .reset => try engine.reset(),
+                    .query => try engine.query_invariants(),
+                }
+            }
+        }
+    };
+
+    const corpus = [_][]const u8{
+        &.{0}, // empty smoke.
+        &.{ 1, 0, 5 }, // literal F at word start.
+        &.{ 1, 0, 9 }, // literal J at word start.
+        &.{ 1, 0, 22 }, // literal W at word start.
+        &.{ 1, 0, 25 }, // literal Z at word start.
+        &.{ 2, 0, 26, 0, 26 }, // circumflex apply.
+        &.{ 2, 0, 0, 0, 48 }, // breve / horn trigger.
+        &.{ 2, 0, 29, 0, 29 }, // stroke apply.
+        &.{ 3, 0, 26, 0, 26, 0, 26 }, // diacritic cancel and literal tail.
+        &.{ 5, 0, 39, 0, 46, 0, 40, 0, 48, 0, 28 }, // autofill family.
+        &.{ 3, 0, 42, 0, 46, 0, 44 }, // QU tone exception family.
+        &.{ 4, 0, 32, 0, 34, 0, 26, 0, 31 }, // GI tone placement family.
+        &.{ 3, 0, 40, 0, 26, 0, 31 }, // OA tone placement family.
+        &.{ 5, 0, 26, 0, 44, 2, 0, 0, 26, 0, 31 }, // reset before suffix.
+        &.{ 5, 0, 26, 0, 26, 0, 26, 1, 0, 0, 26 }, // backspace around literal tail.
+    };
+
+    try std.testing.fuzz({}, Harness.fuzz_one, .{ .corpus = &corpus });
+}
